console.log("updated", guardian.roleId, guardian.policyId);

// verify permission count after update
const tokenCheck = await login(baseUrl, adminEmail, adminPassword);
const perms = await req(baseUrl, tokenCheck, "GET", `/permissions?filter[policy][_eq]=${guardian.policyId}&limit=-1`);
console.log("permission count after update:", perms.data.length, "(expect 3)");

